import { EntitySchema } from '@mikro-orm/core';
import { Wallet } from '../../../domain/entities/wallet.js';
import { Money } from '../../../domain/value-objects/money.js';

export const WalletSchema = new EntitySchema<any>({
  class: Wallet as any,
  tableName: 'wallets',
  properties: {
    id: { type: 'uuid', primary: true },
    playerId: { type: 'string' },
    // currency column is generated by _balance with prefix: false
    _balance: { kind: 'embedded', entity: () => Money, prefix: false },
    _version: { type: 'number', name: 'version', version: true },
    createdAt: { type: 'Date' },
    _updatedAt: { type: 'Date', name: 'updated_at' },
  },
  uniques: [
    { properties: ['playerId', '_balance.currency'] },
  ],
  checks: [
    { name: 'wallet_balance_check', expression: 'amount >= 0' } // updated expression to amount
  ],
});
